import 'dart:convert';

import 'package:crypto/crypto.dart' as hashes;
import 'package:cryptography/cryptography.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:integration_test/integration_test.dart';
import 'package:n42_wallet/core/wallet_sdk/trustdart.dart';

// Public BIP39 fixture; no network requests, real wallet or broadcast.
// Reference generated by scripts/test_near_native.py and independently
// verified with CryptoKit; see test/native/near_reference.json.
void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();
  const mnemonic =
      'abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about';
  const path = "m/44'/397'/0'";
  const reference =
      "CgAAAGFsaWNlLm5lYXIAVRDitEyubrgH4+DkXVed2gWMJ0q8uhXly4Rjb10e5BIEAAAAAAAAAAgAAABib2IubmVhcgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAgICAQAAAAMBAACh7czOG8LTAAAAAAAAAJUBraJ53o31ajFmz+cYUljJqdwABVlNxGib/2LdcPMyjXMVtAhte3Wge8w2CaTIC7sJexMQSvf+ijRr3gkP+Ac=";
  const digestHex =
      "32b101ed2b3f8842f5354da709677be1a4dfb2fa7ca79b6fbeb673a01da22093";
  final sdk = Trustdart();
  Map<String, dynamic> input() => {
    'signerId': 'alice.near',
    'receiverId': 'bob.near',
    'nonce': '4',
    'blockHash': '02' * 32,
    'amount': '010000a1edccce1bc2d3000000000000',
  };
  testWidgets(
    'NATIVE-NEAR-01 real bridge matches independently verified transaction',
    (tester) async {
      await tester.pumpWidget(const MaterialApp(home: Scaffold()));
      final signed = await sdk.signTransaction(
        'NEAR',
        path,
        input(),
        mnemonic: mnemonic,
      );
      expect(signed, reference);
      final bytes = base64Decode(signed);
      final preimage = bytes.sublist(0, bytes.length - 65);
      final digest = hashes.sha256.convert(preimage);
      expect(digest.toString(), digestHex);
      // Borsh prefix: u32 signer length, 10 signer bytes, Ed25519 key tag.
      expect(bytes[14], 0);
      final key = bytes.sublist(15, 47);
      final address = await sdk.generateAddress(
        'NEAR',
        path,
        'legacy',
        mnemonic: mnemonic,
      );
      expect(
        address['legacy'],
        key.map((b) => b.toRadixString(16).padLeft(2, '0')).join(),
      );
      expect(
        await Ed25519().verify(
          digest.bytes,
          signature: Signature(
            bytes.sublist(bytes.length - 64),
            publicKey: SimplePublicKey(key, type: KeyPairType.ed25519),
          ),
        ),
        isTrue,
      );
    },
  );
  testWidgets('NATIVE-NEAR-02 malformed fields fail without crashing bridge', (
    tester,
  ) async {
    await tester.pumpWidget(const MaterialApp(home: Scaffold()));
    final cases = <Map<String, dynamic>>[
      for (final key in input().keys) {...input()}..remove(key),
      {...input(), 'nonce': 4},
      {...input(), 'nonce': '0'},
      {...input(), 'nonce': '9223372036854775808'},
      {...input(), 'signerId': 'Invalid.NEAR'},
      {...input(), 'receiverId': 'bob..near'},
      {...input(), 'blockHash': '02' * 31},
      {...input(), 'amount': '01' * 17},
    ];
    for (final fields in cases) {
      expect(
        await sdk.signTransaction('NEAR', path, fields, mnemonic: mnemonic),
        isEmpty,
      );
    }
    expect(
      await sdk.signTransaction('NEAR', path, input(), mnemonic: mnemonic),
      reference,
    );
  });
}
